const entrada = $('Normalizar Update').first().json;
const partes = entrada.callbackData.split('_'); // ['avanzar', 'PED-...', 'PREP']
const idPedido = partes[1];
const codigo = partes[2];

const ETIQUETAS = {
  PREP: '👨‍🍳 En preparación',
  LISTO: '🔔 Listo para entrega',
  CAMINO: '🛵 En camino',
  ENTREGADO: '✅ Entregado',
  CANCELAR: '❌ Cancelado por cocina'
};

return [{
  json: {
    chatIdCocina: entrada.chatId,
    idPedido,
    codigoEstado: codigo,
    nuevoEstado: ETIQUETAS[codigo] || codigo
  }
}];

const itemsMenu = $input.all();
const itemsCarrito = $('Separar Items Carrito').all();

return itemsMenu.map((item, idx) => {
  const stockActual = Number(item.json.stock || item.json.Stock || 0);
  const nombreProd = String(item.json.nombre || item.json.Nombre || (itemsCarrito[idx]?.json?.carrito?.nombre) || '');
  const itemC = itemsCarrito.find(c => String(c.json.carrito?.nombre || '').trim().toLowerCase() === nombreProd.trim().toLowerCase()) || itemsCarrito[idx];
  const cantidadComprada = Number(itemC?.json?.carrito?.cantidad || 1);
  const nuevoStock = Math.max(0, stockActual - cantidadComprada);

  return {
    json: {
      nombre: nombreProd,
      stock: nuevoStock
    }
  };
});

const entrada = $('Normalizar Update').first().json;
const rawItems = items.map(i => i.json).filter(p => Object.keys(p).length > 0 && (p.id_pedido || p.idPedido));

if (rawItems.length === 0) {
  return [{ json: { ...entrada, caso: 'SIN_PEDIDOS', mensaje: 'No tienes ningún pedido activo en este momento.' } }];
}

// Obtenemos el pedido más reciente del cliente
const ultimo = rawItems[rawItems.length - 1];
const idPedido = ultimo.id_pedido || ultimo.idPedido;
const estado = String(ultimo.estado || '').toLowerCase();

// Si ya está en camino, listo para entrega o entregado -> BLOQUEAR
if (estado.includes('camino') || estado.includes('entregado') || estado.includes('listo')) {
  return [{ json: {
    ...entrada,
    caso: 'BLOQUEADO',
    idPedido,
    mensaje: `⚠️ Tu pedido ${idPedido} ya está en camino o listo para entrega (${ultimo.estado}) y no se puede cancelar directamente. Comunícate con atención si necesitas ayuda.`
  } }];
}

// Si ya estaba cancelado
if (estado.includes('cancelado')) {
  return [{ json: {
    ...entrada,
    caso: 'YA_CANCELADO',
    idPedido,
    mensaje: `El pedido ${idPedido} ya se encuentra cancelado.`
  } }];
}

// Si está en preparación o nuevo -> PERMITIR CANCELACIÓN
return [{ json: {
  ...entrada,
  caso: 'PERMITIDO',
  idPedido,
  detalles: ultimo.detalles || '',
  nuevoEstado: '❌ Cancelado por el cliente'
} }];

const ahora = new Date();

const atascados = items
  .map(i => i.json)
  .filter(p => {
    const estado = String(p.estado || '').toLowerCase();
    return estado.includes('preparación') || estado.includes('preparacion');
  })
  .filter(p => {
    try {
      if (!p.fecha || !p.hora) return false;
      const marcaTiempo = new Date(`${p.fecha}T${p.hora}-05:00`);
      const minutos = (ahora - marcaTiempo) / 60000;
      return Number.isFinite(minutos) && minutos > 45;
    } catch (e) {
      return false;
    }
  });

const idsAtascados = atascados.map(p => p.id_pedido || p.idPedido).filter(Boolean);

return [{
  json: {
    idsAtascados,
    cantidad: idsAtascados.length,
    fechaEjecucion: ahora.toISOString()
  }
}];

const d = $json;
const listaIds = d.idsAtascados.join(', ');
const mensaje = `🚨 ATENCIÓN: Los siguientes pedidos llevan más de 45 min en preparación: [${listaIds}]. Favor verificar en cocina.`;
return [{ json: { ...d, mensaje } }];
